package com.friendinneed.voice;
import org.springframework.context.annotation.Configuration; import org.springframework.web.socket.config.annotation.*;
@Configuration @EnableWebSocket public class WebSocketConfig implements WebSocketConfigurer { private final VoiceStreamEndpoint endpoint; private final com.friendinneed.robot.RobotWebSocketEndpoint robot; public WebSocketConfig(VoiceStreamEndpoint endpoint, com.friendinneed.robot.RobotWebSocketEndpoint robot){this.endpoint=endpoint;this.robot=robot;} public void registerWebSocketHandlers(WebSocketHandlerRegistry registry){registry.addHandler(endpoint,"/ws/voice").setAllowedOriginPatterns("*");registry.addHandler(robot,"/ws/hardware").setAllowedOriginPatterns("*");} }
